using Microsoft.EntityFrameworkCore;
using POS_WPF.Domain.Audit;
using POS_WPF.Domain.Customers;
using POS_WPF.Domain.Finance;
using POS_WPF.Domain.Inventory;
using POS_WPF.Domain.Products;
using POS_WPF.Domain.Promotions;
using POS_WPF.Domain.Purchasing;
using POS_WPF.Domain.Returns;
using POS_WPF.Domain.Security;
using POS_WPF.Domain.Sales;
using POS_WPF.Domain.Settings;
using POS_WPF.Domain.Stores;
using POS_WPF.Domain.Sync;

namespace POS_WPF.Data;

public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Product> Products => Set<Product>(); public DbSet<ProductUnit> ProductUnits => Set<ProductUnit>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<UnitConversionRule> UnitConversionRules => Set<UnitConversionRule>(); public DbSet<InventoryTransaction> InventoryTransactions => Set<InventoryTransaction>();
    public DbSet<User> Users => Set<User>(); public DbSet<Role> Roles => Set<Role>(); public DbSet<UserRole> UserRoles => Set<UserRole>(); public DbSet<RolePermission> RolePermissions => Set<RolePermission>(); public DbSet<Branch> Branches => Set<Branch>(); public DbSet<Warehouse> Warehouses => Set<Warehouse>(); public DbSet<Terminal> Terminals => Set<Terminal>(); public DbSet<CashRegister> CashRegisters => Set<CashRegister>();
    public DbSet<Sale> Sales => Set<Sale>(); public DbSet<Customer> Customers => Set<Customer>(); public DbSet<Supplier> Suppliers => Set<Supplier>(); public DbSet<AccountTransaction> AccountTransactions => Set<AccountTransaction>(); public DbSet<Purchase> Purchases => Set<Purchase>(); public DbSet<SalesReturn> SalesReturns => Set<SalesReturn>(); public DbSet<AuditEntry> AuditEntries => Set<AuditEntry>();
    public DbSet<SyncQueueEntry> SyncQueueEntries => Set<SyncQueueEntry>(); public DbSet<CashMovement> CashMovements => Set<CashMovement>(); public DbSet<StoreSettings> StoreSettings => Set<StoreSettings>(); public DbSet<InvoiceSettings> InvoiceSettings => Set<InvoiceSettings>(); public DbSet<InvoiceFooterLine> InvoiceFooterLines => Set<InvoiceFooterLine>(); public DbSet<TaxSettings> TaxSettings => Set<TaxSettings>(); public DbSet<Promotion> Promotions => Set<Promotion>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // BaseUnitId is intentionally persisted as a scalar reference rather than an EF FK.
        // ProductUnit.ProductId already establishes ownership from unit -> product; making
        // Product.BaseUnitId another FK to ProductUnit creates a required insert cycle that
        // SQLite cannot persist atomically. Domain services validate that BaseUnitId belongs
        // to the same product and is the designated base unit.
        modelBuilder.Entity<Product>(e => { e.HasKey(x => x.Id); e.Property(x => x.Sku).HasMaxLength(64).IsRequired(); e.Property(x => x.Name).HasMaxLength(200).IsRequired(); e.Property(x => x.NameArabic).HasMaxLength(200); e.HasIndex(x => x.Sku).IsUnique(); e.HasOne<Category>().WithMany().HasForeignKey(x => x.CategoryId).OnDelete(DeleteBehavior.Restrict); e.HasMany(x => x.Units).WithOne(x => x.Product).HasForeignKey(x => x.ProductId).OnDelete(DeleteBehavior.Restrict); });
        modelBuilder.Entity<Category>(e => { e.HasKey(x => x.Id); e.Property(x => x.Name).HasMaxLength(150).IsRequired(); e.Property(x => x.NameArabic).HasMaxLength(150); e.HasIndex(x => new { x.ParentCategoryId, x.Name }).IsUnique(); });
        modelBuilder.Entity<ProductUnit>(e => { e.HasKey(x => x.Id); e.Property(x => x.Name).HasMaxLength(100).IsRequired(); e.Property(x => x.Abbreviation).HasMaxLength(20).IsRequired(); e.Property(x => x.Barcode).HasMaxLength(100); e.Property(x => x.ConversionFactorToBase).HasPrecision(18, 6); e.Property(x => x.SellingPrice).HasPrecision(18, 2); e.Property(x => x.PurchasePrice).HasPrecision(18, 2); e.HasIndex(x => x.Barcode).IsUnique().HasFilter("Barcode IS NOT NULL"); e.HasIndex(x => new { x.ProductId, x.Name }).IsUnique(); });
        modelBuilder.Entity<UnitConversionRule>(e => { e.HasKey(x => x.Id); e.Property(x => x.Factor).HasPrecision(18, 6); e.HasIndex(x => new { x.ProductId, x.FromUnitId, x.ToUnitId }).IsUnique(); });
        modelBuilder.Entity<InventoryTransaction>(e => { e.HasKey(x => x.Id); e.Property(x => x.TransactionQuantity).HasPrecision(18, 6); e.Property(x => x.ConversionFactor).HasPrecision(18, 6); e.Property(x => x.BaseQuantity).HasPrecision(18, 6); e.Property(x => x.Reference).HasMaxLength(100); e.HasIndex(x => new { x.ProductId, x.CreatedAt }); e.HasIndex(x => new { x.WarehouseId, x.ProductId, x.CreatedAt }); });
        modelBuilder.Entity<User>(e => { e.HasKey(x => x.Id); e.Property(x => x.Username).HasMaxLength(100).IsRequired(); e.Property(x => x.DisplayName).HasMaxLength(200).IsRequired(); e.Property(x => x.PasswordHash).HasMaxLength(500).IsRequired(); e.HasIndex(x => x.Username).IsUnique(); }); modelBuilder.Entity<Role>(e => { e.HasKey(x => x.Id); e.Property(x => x.Name).HasMaxLength(100).IsRequired(); e.HasIndex(x => x.Name).IsUnique(); }); modelBuilder.Entity<UserRole>(e => e.HasKey(x => new { x.UserId, x.RoleId })); modelBuilder.Entity<RolePermission>(e => { e.HasKey(x => x.PermissionId); e.Property(x => x.PermissionCode).HasMaxLength(150).IsRequired(); e.HasIndex(x => new { x.RoleId, x.PermissionCode }).IsUnique(); });
        modelBuilder.Entity<Branch>(e => { e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(50).IsRequired(); e.Property(x => x.Name).HasMaxLength(200).IsRequired(); e.HasIndex(x => x.Code).IsUnique(); }); modelBuilder.Entity<Warehouse>(e => { e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(50).IsRequired(); e.Property(x => x.Name).HasMaxLength(200).IsRequired(); e.HasIndex(x => new { x.BranchId, x.Code }).IsUnique(); }); modelBuilder.Entity<Terminal>(e => { e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(50).IsRequired(); e.Property(x => x.Name).HasMaxLength(200).IsRequired(); e.HasIndex(x => new { x.BranchId, x.Code }).IsUnique(); }); modelBuilder.Entity<CashRegister>(e => { e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(50).IsRequired(); e.Property(x => x.Name).HasMaxLength(200).IsRequired(); e.HasIndex(x => new { x.BranchId, x.Code }).IsUnique(); e.Property(x => x.OpeningBalance).HasPrecision(18, 2); });
        modelBuilder.Entity<Sale>(e => { e.HasKey(x => x.Id); e.Property(x => x.Number).HasMaxLength(50).IsRequired(); e.HasIndex(x => x.Number).IsUnique(); e.Property(x => x.Subtotal).HasPrecision(18, 2); e.Property(x => x.Discount).HasPrecision(18, 2); e.Property(x => x.Tax).HasPrecision(18, 2); e.Property(x => x.Total).HasPrecision(18, 2); e.HasMany(x => x.Lines).WithOne().HasForeignKey("SaleId").OnDelete(DeleteBehavior.Cascade); e.HasMany(x => x.Payments).WithOne().HasForeignKey("SaleId").OnDelete(DeleteBehavior.Cascade); }); modelBuilder.Entity<SaleLine>(e => { e.HasKey(x => x.Id); e.Property(x => x.Description).HasMaxLength(250).IsRequired(); e.Property(x => x.Quantity).HasPrecision(18, 6); e.Property(x => x.ConversionFactor).HasPrecision(18, 6); e.Property(x => x.UnitPrice).HasPrecision(18, 4); e.Property(x => x.Discount).HasPrecision(18, 2); e.Property(x => x.Tax).HasPrecision(18, 2); }); modelBuilder.Entity<SalePayment>(e => { e.HasKey(x => x.Id); e.Property(x => x.Method).HasMaxLength(50).IsRequired(); e.Property(x => x.Amount).HasPrecision(18, 2); });
        modelBuilder.Entity<Customer>(e => { e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(50).IsRequired(); e.Property(x => x.Name).HasMaxLength(200).IsRequired(); e.Property(x => x.CreditLimit).HasPrecision(18, 2); e.Property(x => x.CurrentBalance).HasPrecision(18, 2); e.HasIndex(x => x.Code).IsUnique(); }); modelBuilder.Entity<Supplier>(e => { e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(50).IsRequired(); e.Property(x => x.Name).HasMaxLength(200).IsRequired(); e.Property(x => x.CurrentBalance).HasPrecision(18, 2); e.HasIndex(x => x.Code).IsUnique(); });
        modelBuilder.Entity<AccountTransaction>(e => { e.HasKey(x => x.Id); e.Property(x => x.Debit).HasPrecision(18, 2); e.Property(x => x.Credit).HasPrecision(18, 2); e.Property(x => x.Reference).HasMaxLength(100).IsRequired(); e.Property(x => x.Notes).HasMaxLength(1000); e.HasIndex(x => new { x.PartyType, x.PartyId, x.CreatedAtUtc }); });
        modelBuilder.Entity<Purchase>(e => { e.HasKey(x => x.Id); e.Property(x => x.Number).HasMaxLength(50).IsRequired(); e.HasIndex(x => x.Number).IsUnique(); e.Property(x => x.Subtotal).HasPrecision(18, 2); e.Property(x => x.Discount).HasPrecision(18, 2); e.Property(x => x.Tax).HasPrecision(18, 2); e.Property(x => x.Total).HasPrecision(18, 2); e.HasMany(x => x.Lines).WithOne().HasForeignKey("PurchaseId").OnDelete(DeleteBehavior.Cascade); }); modelBuilder.Entity<PurchaseLine>(e => { e.HasKey(x => x.Id); e.Property(x => x.Quantity).HasPrecision(18, 6); e.Property(x => x.ConversionFactor).HasPrecision(18, 6); e.Property(x => x.UnitCost).HasPrecision(18, 4); e.Property(x => x.Discount).HasPrecision(18, 2); e.Property(x => x.Tax).HasPrecision(18, 2); });
        modelBuilder.Entity<SalesReturn>(e => { e.HasKey(x => x.Id); e.Property(x => x.Number).HasMaxLength(50).IsRequired(); e.HasIndex(x => x.Number).IsUnique(); e.HasMany(x => x.Lines).WithOne().HasForeignKey("SalesReturnId").OnDelete(DeleteBehavior.Cascade); }); modelBuilder.Entity<SalesReturnLine>(e => { e.HasKey(x => x.Id); e.Property(x => x.Quantity).HasPrecision(18, 6); e.Property(x => x.HistoricalConversionFactor).HasPrecision(18, 6); e.Property(x => x.UnitPrice).HasPrecision(18, 4); });
        modelBuilder.Entity<CashMovement>(e => { e.HasKey(x => x.Id); e.Property(x => x.Amount).HasPrecision(18, 2); e.Property(x => x.Reference).HasMaxLength(100).IsRequired(); e.HasIndex(x => new { x.RegisterId, x.CreatedAtUtc }); }); modelBuilder.Entity<AuditEntry>(e => { e.HasKey(x => x.Id); e.Property(x => x.Action).HasMaxLength(100).IsRequired(); e.Property(x => x.EntityType).HasMaxLength(100).IsRequired(); e.Property(x => x.OldValue).HasMaxLength(4000); e.Property(x => x.NewValue).HasMaxLength(4000); e.Property(x => x.Reason).HasMaxLength(1000); e.Property(x => x.Details).HasMaxLength(4000); e.HasIndex(x => new { x.EntityType, x.EntityId, x.CreatedAtUtc }); });
        modelBuilder.Entity<SyncQueueEntry>(e => { e.HasKey(x => x.Id); e.Property(x => x.EntityType).HasMaxLength(100).IsRequired(); e.Property(x => x.Operation).HasMaxLength(50).IsRequired(); e.Property(x => x.Payload).IsRequired(); e.Property(x => x.LastError).HasMaxLength(2000); e.HasIndex(x => new { x.Status, x.CreatedAtUtc }); }); modelBuilder.Entity<StoreSettings>(e => { e.HasKey(x => x.Id); e.Property(x => x.StoreName).HasMaxLength(200).IsRequired(); e.Property(x => x.CurrencyCode).HasMaxLength(10).IsRequired(); e.Property(x => x.LogoPath).HasMaxLength(500); e.HasIndex(x => x.BranchId).IsUnique(); }); modelBuilder.Entity<InvoiceSettings>(e => { e.HasKey(x => x.Id); e.Property(x => x.HeaderText).HasMaxLength(1000); e.HasMany(x => x.FooterLines).WithOne().HasForeignKey("InvoiceSettingsId").OnDelete(DeleteBehavior.Cascade); }); modelBuilder.Entity<InvoiceFooterLine>(e => { e.HasKey(x => x.Id); e.Property(x => x.Text).HasMaxLength(500).IsRequired(); }); modelBuilder.Entity<TaxSettings>(e => { e.HasKey(x => x.Id); e.Property(x => x.Rate).HasPrecision(9, 4); }); modelBuilder.Entity<Promotion>(e => { e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(50).IsRequired(); e.Property(x => x.Name).HasMaxLength(200).IsRequired(); e.HasIndex(x => x.Code).IsUnique(); e.Property(x => x.Value).HasPrecision(18, 4); e.Property(x => x.MinimumQuantity).HasPrecision(18, 6); e.Property(x => x.RewardQuantity).HasPrecision(18, 6); });
    }
}
